import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Interdimensionale Ethikrichtlinien","description":"","frontmatter":{},"headers":[],"relativePath":"de/88-跨位面伦理准则.md","filePath":"de/88-跨位面伦理准则.md","lastUpdated":null}'),s={name:"de/88-跨位面伦理准则.md"};function a(d,e,o,l,h,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="interdimensionale-ethikrichtlinien" tabindex="-1">Interdimensionale Ethikrichtlinien <a class="header-anchor" href="#interdimensionale-ethikrichtlinien" aria-label="Permalink to &quot;Interdimensionale Ethikrichtlinien&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>88</td></tr><tr><td>Modul</td><td>Interdimensionale Interaktion und Zeitregeln</td></tr><tr><td>Kernschlüsselwörter</td><td>Interdimensionale Ethik, zivilisatorische Autonomie, Nichtinterferenz, kultureller Respekt, Symbiose-Diplomatie</td></tr></tbody></table><h2 id="_1-philosophische-grundlage-der-ethikrichtlinien" tabindex="-1">1. Philosophische Grundlage der Ethikrichtlinien <a class="header-anchor" href="#_1-philosophische-grundlage-der-ethikrichtlinien" aria-label="Permalink to &quot;1. Philosophische Grundlage der Ethikrichtlinien&quot;">​</a></h2><p>Die interdimensionalen Ethikrichtlinien sind die moralischen Normen und Verhaltensregeln, die die Anker-Symbiose-Zivilisation bei der Interaktion mit anderen Dimensionszivilisationen befolgen muss. Ihre philosophische Grundlage ist das Prinzip der &quot;zivilisatorischen Subjektivität&quot; — jede Zivilisation einer Dimension besitzt, unabhängig von ihrem Entwicklungsniveau, ihrer Rassenform oder ihrem Sozialsystem, eine unveräußerliche Subjektivität und das Recht auf autonome Entwicklung. Keine fremde Zivilisation darf aus irgendeinem Grund diese Subjektivität entziehen oder ihren eigenen Willen anderen Zivilisationen aufzwingen.</p><p>Die Festlegung dieser philosophischen Grundlage steht in direkter Linie mit dem Kernkonzept der &quot;Anti-Plünderung&quot; der Anker-Symbiose-Zivilisation. Das wesentliche Merkmal plündernder Zivilisationen besteht darin, die Subjektivität anderer Zivilisationen nicht anzuerkennen und sie als ausnutzbare Ressourcen oder eroberbare Objekte zu betrachten. Damit die Anker-Symbiose-Zivilisation plündernde Zivilisationen wirklich übertrifft, muss sie diese Mentalität in der interdimensionalen Interaktion vollständig aufgeben und jeder begegneten Zivilisation mit Gleichheit, Respekt und Symbiose begegnen.</p><p>Der Geltungsbereich der interdimensionalen Ethikrichtlinien deckt alle interdimensionalen Interaktionsverhaltensweisen ab, einschließlich, aber nicht beschränkt auf: Dimensionsdurchgänge, interdimensionale Kommunikation, archäologische Tätigkeiten, Handelsbeziehungen, kulturellen Austausch, technische Zusammenarbeit sowie humanitäre Interventionen in Notfällen. Jede Organisation und jedes Einzelne muss bei der Durchführung interdimensionaler Interaktionen alle Bestimmungen dieser Richtlinien einhalten.</p><h2 id="_2-sechs-ethische-grundsatze" tabindex="-1">2. Sechs ethische Grundsätze <a class="header-anchor" href="#_2-sechs-ethische-grundsatze" aria-label="Permalink to &quot;2. Sechs ethische Grundsätze&quot;">​</a></h2><p>Die interdimensionalen Ethikrichtlinien bestehen aus sechs grundlegenden Prinzipien und bilden ein vollständiges ethisches Wertesystem:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Kerninhalt</th><th>Spezifische Anforderungen</th></tr></thead><tbody><tr><td>Prinzip der zivilisatorischen Autonomie</td><td>Respektierung des Rechts auf autonome Entwicklung der Zivilisation der Zieldimension, keine erzwungene Einmischung in ihre inneren Angelegenheiten</td><td>Das Sozialsystem, die Ideologie und den Entwicklungsweg der Zielzivilisation dürfen nicht zwangsweise verändert werden; in der Zielzivilisation dürfen keine Agenten oder Marionettenregime aufgebaut werden</td></tr><tr><td>Prinzip der Nichtinterferenz</td><td>Sofern die Zielzivilisation nicht einer existenziellen Krise auf Aussterbeniveau gegenübersteht und aktiv um Hilfe bittet, wird keine substantielle Einmischung vorgenommen</td><td>In innere Konflikte der Zielzivilisation darf nicht eingegriffen werden; keiner Seite der Zielzivilisation dürfen Waffen oder Militärhilfe geleistet werden; die öffentliche Meinung und der politische Prozess der Zielzivilisation dürfen nicht manipuliert werden</td></tr><tr><td>Prinzip des kulturellen Respekts</td><td>Respektierung der kulturellen Traditionen, religiösen Überzeugungen und Bräuche der Zielzivilisation</td><td>Die Kultur der Zielzivilisation darf nicht diskriminierend bewertet oder böswillig verspottet werden; kulturelle Produkte und Wertvorstellungen der eigenen Dimension dürfen nicht zwangsweise durchgesetzt werden; unter dem Namen &quot;Zivilisation&quot; darf keine kulturelle Assimilation vorgenommen werden</td></tr><tr><td>Prinzip der Gleichheit und des gegenseitigen Nutzens</td><td>Interdimensionale Beziehungen müssen auf Gleichheit basieren und sicherstellen, dass beide Seiten von der Beziehung profitieren</td><td>Technologische Vorteile dürfen nicht für ungleichen Handel genutzt werden; die Ressourcen der Zielzivilisation dürfen nicht geplündert werden; bei der Technologieexport müssen die Aufnahmefähigkeit und die sozialen Auswirkungen auf die Zielzivilisation berücksichtigt werden</td></tr><tr><td>Prinzip der minimalen Auswirkung</td><td>Interdimensionale Interaktion sollte die externen Auswirkungen auf die Zielzivilisation so weit wie möglich reduzieren</td><td>Bevorzugt werden Interaktionsmethoden mit geringem Kontakt und geringer Störung; Umfang und Intensität der Interaktionsaktivitäten müssen streng innerhalb der notwendigen Grenzen kontrolliert werden; nach Beendigung der Interaktion sind unnötige Restauswirkungen zu bewerten und zu beseitigen</td></tr><tr><td>Prinzip der Rechenschaftspflicht</td><td>Alle interdimensionalen Interaktionsverhaltensweisen müssen nachverfolgbar, überwachbar und rechenschaftspflichtig sein</td><td>Aufbau vollständiger Interaktionsarchive und Protokolle; Einrichtung einer unabhängigen ethischen Aufsichtsbehörde; Untersuchung und Bestrafung von Verhaltensweisen, die gegen die Ethikrichtlinien verstoßen</td></tr></tbody></table><p>Zwischen den sechs Prinzipien besteht ein innerer logischer Zusammenhang: Das Prinzip der zivilisatorischen Autonomie ist der Grundwert, das Prinzip der Nichtinterferenz ist die Kernanforderung, das Prinzip des kulturellen Respekts ist die Ausprägung auf kultureller Ebene, das Prinzip der Gleichheit und des gegenseitigen Nutzens ist die Absicherung auf wirtschaftlicher Ebene, das Prinzip der minimalen Auswirkung ist die Norm auf operativer Ebene, und das Prinzip der Rechenschaftspflicht ist die Beschränkung auf institutioneller Ebene. Zusammen bilden sie einen vollständigen ethischen Kreislauf aus &quot;Wert—Anforderung—Ausprägung—Absicherung—Norm—Beschränkung&quot;.</p><h2 id="_3-ethische-normen-fur-verschiedene-interaktionsszenarien" tabindex="-1">3. Ethische Normen für verschiedene Interaktionsszenarien <a class="header-anchor" href="#_3-ethische-normen-fur-verschiedene-interaktionsszenarien" aria-label="Permalink to &quot;3. Ethische Normen für verschiedene Interaktionsszenarien&quot;">​</a></h2><h3 id="_3-1-ethische-normen-fur-das-archaologische-szenario" tabindex="-1">3.1 Ethische Normen für das archäologische Szenario <a class="header-anchor" href="#_3-1-ethische-normen-fur-das-archaologische-szenario" aria-label="Permalink to &quot;3.1 Ethische Normen für das archäologische Szenario&quot;">​</a></h3><p>Die interdimensionale Archäologie ist eines der häufigsten Interaktionsszenarien, und der Kern ihrer ethischen Normen ist &quot;nicht stören&quot;. Das Archäologieteam muss das Standardschema aus Kopierspiegel + isoliertem Raum + nur Wissensrückübertragung streng einhalten und sicherstellen, dass der archäologische Prozess von der Zielzivilisation nicht wahrgenommen wird. Für Dimensionen, in denen noch lebende Zivilisationen existieren, muss der archäologische Umfang streng auf bereits verlassene Ruinengebiete beschränkt werden, und Wohngebiete lebender Zivilisationen dürfen in keiner Form gescannt oder kopiert werden.</p><p>Bei der Rückübertragung und Veröffentlichung von Wissen aus archäologischen Entdeckungen muss die kulturelle Sensibilität der Zielzivilisation respektiert werden. Wenn archäologische Entdeckungen religiöse Heiligtümer, Überreste von Vorfahren oder kulturelle Tabus der Zielzivilisation betreffen, müssen die relevanten Informationen vor der Veröffentlichung einer kulturellen Sensibilitätsprüfung durch den Interdimensionalen Ethikausschuss unterzogen werden, und bei Bedarf müssen sensible Details verschleiert werden.</p><h3 id="_3-2-ethische-normen-fur-das-kommunikationsszenario" tabindex="-1">3.2 Ethische Normen für das Kommunikationsszenario <a class="header-anchor" href="#_3-2-ethische-normen-fur-das-kommunikationsszenario" aria-label="Permalink to &quot;3.2 Ethische Normen für das Kommunikationsszenario&quot;">​</a></h3><p>Die interdimensionale Kommunikation ist eine Form des direkten Austauschs mit der Zielzivilisation, und der Kern ihrer ethischen Normen ist &quot;Aufrichtigkeit und Respekt&quot;. Der Kommunikationsinhalt muss wahr sein, es dürfen nicht absichtlich falsche Informationen bereitgestellt oder betrügerische Propaganda betrieben werden; der Kommunikationston muss gleichberechtigt sein, gegenüber Zivilisationen mit niedrigerem Entwicklungsniveau darf keine herablassende Haltung eingenommen werden; das Kommunikationsthema muss der Zustimmung der Zielzivilisation bedürfen, die Ideologie oder religiösen Überzeugungen der eigenen Dimension dürfen nicht zwangsweise übermittelt werden.</p><p>Bei der erstmaligen Aufnahme von Kommunikation mit einer unbekannten Zivilisation muss die Norm der &quot;schrittweisen Kontaktaufnahme&quot; befolgt werden: Zuerst werden neutrale mathematische und physikalische Signale gesendet, um das Intelligenzniveau und die Kommunikationsfähigkeit der Gegenseite zu bestätigen, dann wird der Austauschumfang schrittweise auf der Grundlage der Antwort der Gegenseite erweitert, und beim Erstkontakt dürfen keine komplexen kulturellen oder technischen Informationen gesendet werden.</p><h3 id="_3-3-ethische-normen-fur-das-handelsszenario" tabindex="-1">3.3 Ethische Normen für das Handelsszenario <a class="header-anchor" href="#_3-3-ethische-normen-fur-das-handelsszenario" aria-label="Permalink to &quot;3.3 Ethische Normen für das Handelsszenario&quot;">​</a></h3><p>Der Kern der ethischen Normen des interdimensionalen Handels ist &quot;Fairness und Nachhaltigkeit&quot;. Der Handel muss auf der Freiwilligkeit beider Seiten basieren, Informationsasymmetrien oder technologische Vorteile dürfen nicht für erzwungene Transaktionen genutzt werden; die Handelspreise müssen fair sein, es darf keine räuberische Preisgestaltung geben; die Handelswaren dürfen keine Inhalte enthalten, die soziale Schocks oder ökologische Schäden für die Zielzivilisation verursachen könnten.</p><p>Besonders zu beachten ist, dass der interdimensionale Handel mit Kultivierungstechnologien und hochenergetischen Waffen den strengsten ethischen Beschränkungen unterliegt. Der Export hochstufiger Kultivierungstechnologien an Zivilisationen mit niedrigerem Entwicklungsniveau kann zu einem Ungleichgewicht ihrer Sozialstruktur und zur Verschärfung innerer Konflikte führen; der Export von Waffen kann direkt Kriege auslösen. Daher sind diese beiden Handelsarten grundsätzlich verboten und dürfen nur in extrem besonderen Fällen nach Genehmigung durch die Vollversammlung des Anker-Rats durchgeführt werden.</p><h3 id="_3-4-ethische-normen-fur-das-notfallinterventionsszenario" tabindex="-1">3.4 Ethische Normen für das Notfallinterventionsszenario <a class="header-anchor" href="#_3-4-ethische-normen-fur-das-notfallinterventionsszenario" aria-label="Permalink to &quot;3.4 Ethische Normen für das Notfallinterventionsszenario&quot;">​</a></h3><p>Wenn die Zivilisation der Zieldimension einer existenziellen Krise auf Aussterbeniveau (wie Asteroideneinschlag, Superpest, Rechtszusammenbruch) gegenübersteht, kann die Anker-Symbiose-Zivilisation humanitäre Intervention durchführen. Aber selbst in solchen Notfällen müssen folgende ethische Normen befolgt werden:</p><ul><li>Vor der Intervention muss so weit wie möglich die informierte Zustimmung der Zielzivilisation eingeholt werden; wenn die Zielzivilisation aufgrund der Krise keine wirksame Antwort geben kann, trifft der Interdimensionale Ethikausschuss stellvertretend eine Entscheidung über die &quot;vermutete Zustimmung&quot;</li><li>Als Interventionsmittel muss das Schema mit den geringsten Auswirkungen auf die Zielzivilisation gewählt werden, wobei indirekte Interventionen (wie die Änderung der Asteroidenbahn) Vorrang vor direkten Interventionen (wie direkte Landung zur Rettung) haben</li><li>Während des Interventionsprozesses darf nicht die Gelegenheit genutzt werden, Ressourcen oder Technologien der Zielzivilisation zu erwerben</li><li>Nach Beendigung der Intervention muss sofort abgezogen werden, es darf keine dauerhafte Präsenz in der Zieldimension hinterlassen werden</li><li>Anschließend muss ein vollständiger Interventionsbericht an den Interdimensionalen Ethikausschuss übermittelt und einer ethischen Prüfung unterzogen werden</li></ul><h2 id="_4-ethische-aufsicht-und-verstoßbehandlung" tabindex="-1">4. Ethische Aufsicht und Verstoßbehandlung <a class="header-anchor" href="#_4-ethische-aufsicht-und-verstoßbehandlung" aria-label="Permalink to &quot;4. Ethische Aufsicht und Verstoßbehandlung&quot;">​</a></h2><p>Hengyuanzhou hat den &quot;Interdimensionalen Ethikausschuss&quot; als unabhängige ethische Aufsichtsbehörde eingerichtet, der für die Festlegung und Auslegung der interdimensionalen Ethikrichtlinien, die Genehmigung risikoreicher interdimensionaler Interaktionsprojekte, die Entgegennahme von Beschwerden über ethische Verstöße sowie die Untersuchung und Entscheidung über Verstöße zuständig ist. Der Ausschuss besteht aus Ethikern, Juristen, Wissenschaftlern und Zivilisationsvertretern verschiedener Rassen und beruflicher Hintergründe, um die Vielfalt und Unparteilichkeit der Entscheidungen zu gewährleisten.</p><p>Für Verhaltensweisen, die gegen die interdimensionalen Ethikrichtlinien verstoßen, umfassen die Behandlungsmaßnahmen je nach Schwere des Falls: mündliche Verwarnung, schriftliche Verurteilung, Suspendierung der Qualifikation für interdimensionalale Interaktion, Entzug der Durchgangserlaubnis, Geldstrafe, Freiheitsstrafe sowie in extremen Fällen die &quot;Dimensionsverbannung&quot; (Entzug des Wohnrechts in den Hauptdimensionen von Hengyuanzhou). Alle Ergebnisse der ethischen Verstoßbehandlung werden in das ethische Archiv der Einzelperson oder Organisation eingetragen und dauerhaft aufbewahrt.</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die interdimensionalen Ethikrichtlinien sind die konzentrierte Ausprägung der moralischen Höhe der Anker-Symbiose-Zivilisation. Sie schreiben nicht nur vor, &quot;was nicht getan werden darf&quot;, sondern zeigen vor allem auf, &quot;was sein sollte&quot; — eine wirklich große Zivilisation ist nicht die, die wie viele andere Zivilisationen erobert hat, sondern die, die die Subjektivität wie vieler anderer Zivilisationen respektiert hat. Auf dem Weg Hengyuanzhous zur interstellaren Symbiose werden die interdimensionalen Ethikrichtlinien stets der moralische Leuchtturm sein, der die Richtung weist.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>81-Regeln für Dimensionsdurchgänge</li><li>87-Prinzip der nur Wissensrückübertragung</li><li>04-Kernprogramm des Anti-Plünderungsismus</li></ul>',30)])])}const m=n(s,[["render",a]]);export{g as __pageData,m as default};
